rule.definition:
if(
  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!interview),
  'type!{urn:com:appian:types:CAW}CAW_GENERIC_Interview_Validation'(
    interviewer: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3874725"
  ),
  if(
    property(ri!interview,"isComplete",false)=true,
    'type!{urn:com:appian:types:CAW}CAW_GENERIC_Interview_Validation'(),
    if(
      ri!interviewerTask = true,
      'type!{urn:com:appian:types:CAW}CAW_GENERIC_Interview_Validation'(
        interviewFeedback: if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!interview,"interviewFeedback",null)),
          #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3874725",
          null
        ),
        supportExtensionOfOffer: if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!interview,"supportExtensionOfOffer",null)),
          #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3874725",
          null
        )
      ),
      'type!{urn:com:appian:types:CAW}CAW_GENERIC_Interview_Validation'(
        interviewer: if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!interview,"interviewerId",null)),
          #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3874725",
          null
        ),
        interviewLocation: if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!interview,"interviewDateTime",null)),
          null,
          if(
            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!interview,"interviewLocation",null)),
            #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3874725",
            null
          )
        ),
        officeLocation: if(
          and(
            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!interview,"interviewOfficeLocation",null)),
            property(ri!interview,"interviewLocation","") = "Office"
          ),
          #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3874725",
          null
        )
      )
    )
  )
)
